const input = $input.first().json;
const execution = input.execution || {};
const error = execution.error || input.error || {};

// Workflow name: extract from execution URL
const url = execution.url || '';
const workflowId = url.match(/\/workflow\/([^\/]+)\//)?.[1] || 'N/A';
const workflow = `Workflow ID: ${workflowId}`;

// Failed node is on execution, not error
const node = execution.lastNodeExecuted || error.lastNodeExecuted || 'Unknown Node';

// Error message is on execution.error
const message = error.message || error.description || 'No error message';

const executionId = execution.id || 'N/A';
const timestamp = new Date().toISOString();

const slackMessage = `🔥 *n8n Workflow Error Alert*\n\n*${workflow}*\n*Failed Node:* ${node}\n*Execution ID:* ${executionId}\n*Time:* ${timestamp}\n\n*Error Message:*\n\`\`\`\n${message}\n\`\`\`\n\n🔗 <${url}|View Execution>`;

return [{
  json: {
    timestamp, workflow, node, message, executionId,
    errorDetails: JSON.stringify(input, null, 2),
    severity: 'high',
    text: slackMessage
  }
}];
